1	{
2	  "name": "feature-harbor",
3	  "version": "0.1.0",
4	  "private": true,
5	  "type": "module",
6	  "scripts": {
7	    "start": "node server.ts serve",
8	    "help": "node server.ts --help",
9	    "test": "node --test"
10	  }
11	}
12

1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	
7	const PRODUCT: string = 'FeatureHarbor';
8	const RESOURCE: string = 'ideas';
9	const MAX_TITLE = 120;
10	const MAX_DESCRIPTION = 5000;
11	const MAX_SCENARIO = 1000;
12	const MAX_BODY_BYTES = 1_000_000;
13	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
14	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
15	a{color:#175b9c}
16	label{display:block;font-weight:600;margin-top:1rem}
17	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
18	textarea{resize:vertical}
19	.required{color:#b00020}
20	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
21	#error{color:#b00020;margin-top:.75rem}
22	#success{color:#1a7f37;margin-top:.75rem}
23	.idea{border-top:1px solid #ddd;padding:1rem 0}
24	.idea h3{margin:0 0 .5rem}
25	.pre{white-space:pre-wrap}
26	time{color:#666;font-size:.9rem}
27	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
28	<h2>提交产品意见</h2>
29	<form id="idea-form" novalidate>
30	<label for="f-title">标题 <span class="required">*</span>（必填，最多 120 字）</label>
31	<input id="f-title" name="title" required>
32	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 5000 字）</label>
33	<textarea id="f-desc" name="description" rows="5" required></textarea>
34	<label for="f-scenario">使用场景（可选，最多 1000 字）</label>
35	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
36	<button type="submit">提交意见</button>
37	<p id="error" role="alert" hidden></p>
38	<p id="success" role="status" hidden></p>
39	</form>
40	<h2>意见列表</h2>
41	<p id="empty" hidden>还没有意见记录。</p>
42	<div id="ideas"></div>
43	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
44	</main><script>
45	const form = document.getElementById('idea-form');
46	const titleInput = document.getElementById('f-title');
47	const descInput = document.getElementById('f-desc');
48	const scenarioInput = document.getElementById('f-scenario');
49	const errorBox = document.getElementById('error');
50	const successBox = document.getElementById('success');
51	const emptyNote = document.getElementById('empty');
52	const list = document.getElementById('ideas');
53	const EMPTY_TEXT = '还没有意见记录。';
54	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
55	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
56	let listState = 'loading';
57	function codePoints(text) { return Array.from(text).length; }
58	function showError(message) {
59	  errorBox.textContent = message;
60	  errorBox.hidden = false;
61	  successBox.hidden = true;
62	}
63	function renderIdea(idea) {
64	  const item = document.createElement('article');
65	  item.className = 'idea';
66	  const heading = document.createElement('h3');
67	  heading.textContent = idea.title;
68	  const desc = document.createElement('p');
69	  desc.className = 'pre';
70	  desc.textContent = idea.description;
71	  item.append(heading, desc);
72	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
73	    const scenario = document.createElement('p');
74	    const label = document.createElement('strong');
75	    label.textContent = '使用场景：';
76	    const text = document.createElement('span');
77	    text.className = 'pre';
78	    text.textContent = idea.scenario;
79	    scenario.append(label, text);
80	    item.append(scenario);
81	  }
82	  const time = document.createElement('time');
83	  time.dateTime = idea.createdAt;
84	  const parsed = new Date(idea.createdAt);
85	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
86	  item.append(time);
87	  return item;
88	}
89	let remoteIdeas = [];
90	// 本页已确认保存的意见，按本页发起提交的先后排列：后提交的在前。
91	// 每条记录带上点击提交时的序号，响应返回的先后不影响排列位置
92	const submittedIdeas = [];
93	function renderList() {
94	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
95	  const seen = new Set();
96	  const ordered = [];
97	  for (const entry of submittedIdeas) {
98	    const idea = entry.idea;
99	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
100	  }
101	  for (const idea of remoteIdeas) {
102	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
103	  }
104	  list.replaceChildren(...ordered.map(renderIdea));
105	  if (listState === 'failed') {
106	    emptyNote.textContent = LOAD_FAILED_TEXT;
107	    emptyNote.hidden = false;
108	  } else if (listState === 'ready') {
109	    emptyNote.textContent = EMPTY_TEXT;
110	    emptyNote.hidden = ordered.length > 0;
111	  } else {
112	    // 首次列表仍在加载，不能把等待误报成没有记录
113	    emptyNote.hidden = true;
114	  }
115	}
116	// 一条有效意见必须是 JSON 对象：id 为非空字符串，
117	// title、description、scenario、createdAt 均为字符串（scenario 允许为空字符串）
118	function isValidIdea(idea) {
119	  if (typeof idea !== 'object' || idea === null || Array.isArray(idea)) return false;
120	  if (typeof idea.id !== 'string' || idea.id.length === 0) return false;
121	  for (const field of ['title', 'description', 'scenario', 'createdAt']) {
122	    if (typeof idea[field] !== 'string') return false;
123	  }
124	  return true;
125	}
126	async function loadIdeas() {
127	  try {
128	    const res = await fetch('/api/ideas');
129	    if (!res.ok) throw new Error('load failed');
130	    const data = await res.json();
131	    // 列表响应必须是带 ideas 数组的 JSON 对象，且数组中每条记录都合法；
132	    // 顶层结构异常或任意一条记录异常都属于整次加载失败，
133	    // 即使异常记录前面有正常意见，也不能只展示其中一部分
134	    if (typeof data !== 'object' || data === null || Array.isArray(data) || !Array.isArray(data.ideas)) {
135	      throw new Error('invalid ideas response');
136	    }
137	    if (!data.ideas.every(isValidIdea)) throw new Error('invalid idea record');
138	    remoteIdeas = data.ideas;
139	    listState = 'ready';
140	  } catch {
141	    listState = 'failed';
142	  }
143	  renderList();
144	}
145	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
146	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
147	let editVersion = 0;
148	for (const field of [titleInput, descInput, scenarioInput]) {
149	  field.addEventListener('input', () => { editVersion += 1; });
150	}
151	function validate(title, description, scenario) {
152	  const trimmed = title.trim();
153	  if (!trimmed) return '标题不能为空。';
154	  if (codePoints(trimmed) > 120) return '标题最多 120 个字符。';
155	  if (!description.trim()) return '详细说明不能为空。';
156	  if (codePoints(description) > 5000) return '详细说明最多 5000 个字符。';
157	  if (codePoints(scenario) > 1000) return '使用场景最多 1000 个字符。';
158	  return null;
159	}
160	// 每次点击提交都递增：成功或失败提示只属于最近一次点击。
161	// 更早发出的请求即使更晚返回，也只能在服务确认保存时更新列表，不能改动当前提示。
162	let latestSubmitSeq = 0;
163	form.addEventListener('submit', async (event) => {
164	  event.preventDefault();
165	  const submitSeq = ++latestSubmitSeq;
166	  // 用户发起新的提交后，上一条操作的提示先清除；在本次点击有结果前，
167	  // 更早请求迟到返回也不能重新显示成功或失败，也不能让人误以为正在提交的意见已保存
168	  errorBox.hidden = true;
169	  successBox.hidden = true;
170	  const title = titleInput.value;
171	  const description = descInput.value;
172	  const scenario = scenarioInput.value;
173	  const submittedVersion = editVersion;
174	  const problem = validate(title, description, scenario);
175	  // 被表单直接拦下的一次点击同样是用户最近的提交操作，字段错误即本次点击的结果；
176	  // 之后更早请求的返回不能掩盖它
177	  if (problem) { showError(problem); return; }
178	  let res;
179	  try {
180	    res = await fetch('/api/ideas', {
181	      method: 'POST',
182	      headers: { 'content-type': 'application/json' },
183	      body: JSON.stringify({ title, description, scenario })
184	    });
185	  } catch {
186	    if (submitSeq === latestSubmitSeq) showError('网络错误，提交未成功，请重试。');
187	    return;
188	  }
189	  let data = null;
190	  try { data = await res.json(); } catch { data = null; }
191	  if (!res.ok) {
192	    if (submitSeq === latestSubmitSeq) {
193	      showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
194	    }
195	    return;
196	  }
197	  // 成功状态的响应同样必须结构完整：顶层是含 idea 的 JSON 对象，
198	  // 且 idea 本身通过 isValidIdea 校验（对象、非空 id、各字段均为字符串）。
199	  // 空对象、数组或缺字段的记录不能当作保存成功：不显示成功提示、
200	  // 不清空草稿、不并入列表，也不用表单内容补齐响应缺失的信息
201	  const saved = typeof data === 'object' && data !== null && !Array.isArray(data) && isValidIdea(data.idea);
202	  if (!saved) {
203	    if (submitSeq === latestSubmitSeq) showError('提交失败，请稍后重试。');
204	    return;
205	  }
206	  const idea = data.idea;
207	  // 是否清空表单只取决于等待期间有没有继续编辑（包括改回原文、清空字段也算编辑），
208	  // 与响应返回先后无关：过期请求确认保存时也不能清掉用户正在写的草稿
209	  if (editVersion === submittedVersion) form.reset();
210	  // 只要服务确认保存，意见就进入列表，即使这条请求已不是最近一次点击：
211	  // 不能为了避免提示干扰而丢弃真实保存结果。
212	  // 位置按本页发起提交的先后确定（后提交的在前），与响应返回先后无关：
213	  // 先提交的意见迟到确认时补到后提交的意见之后，不能把它挤到更靠后的位置
214	  const entry = { seq: submitSeq, idea };
215	  let insertAt = submittedIdeas.findIndex((e) => e.seq < submitSeq);
216	  if (insertAt === -1) insertAt = submittedIdeas.length;
217	  submittedIdeas.splice(insertAt, 0, entry);
218	  renderList();
219	  // 成功提示只属于最近一次点击：更早的请求迟到返回时，不能在最新一次的失败提示
220	  // 或新一次提交的等待旁边再显示成功
221	  if (submitSeq === latestSubmitSeq) {
222	    successBox.textContent = '提交成功，你的意见已保存。';
223	    successBox.hidden = false;
224	  }
225	});
226	loadIdeas();
227	</script></html>`;
228	const args: string[] = process.argv.slice(2);
229	const help: string = `FeatureHarbor - 产品意见与公开路线图
230	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
231	       node server.ts --help
232	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
233	Port 0 selects an available port.
234	`;
235	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
236	  process.stdout.write(help);
237	  process.exit(args.length === 0 ? 2 : 0);
238	}
239	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
240	let host: string = '127.0.0.1';
241	let port: number = 8080;
242	let dataDir: string = 'data';
243	while (args.length) {
244	  const flag = args.shift();
245	  const value = args.shift();
246	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
247	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
248	  }
249	  if (flag === '--host') host = value;
250	  else if (flag === '--port') {
251	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
252	    port = Number(value);
253	  } else dataDir = value;
254	}
255	mkdirSync(dataDir, { recursive: true });
256	const dataFile = join(dataDir, 'ideas.json');
257	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
258	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
259	}
260	function respond(res: ServerResponse, status: number, value: unknown, options: { html?: boolean; allow?: string } = {}): void {
261	  const body = options.html ? String(value) : JSON.stringify(value);
262	  res.writeHead(status, { 'content-type': options.html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
263	    'content-length': Buffer.byteLength(body), ...(status === 405 ? { allow: options.allow ?? 'GET' } : {}) });
264	  res.end(body);
265	}
266	function codePoints(text: string): number {
267	  return Array.from(text).length;
268	}
269	function readIdeas(): unknown[] {
270	  const records: unknown = JSON.parse(readFileSync(dataFile, 'utf8'));
271	  if (!Array.isArray(records)) throw new Error('Invalid record list');
272	  return records;
273	}
274	function saveIdeas(records: unknown[]): void {
275	  const tempFile = `${dataFile}.tmp`;
276	  writeFileSync(tempFile, `${JSON.stringify(records, null, 2)}\n`);
277	  renameSync(tempFile, dataFile);
278	}
279	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
280	  const chunks: Buffer[] = [];
281	  let size = 0;
282	  for await (const chunk of req as AsyncIterable<Buffer>) {
283	    size += chunk.length;
284	    if (size > MAX_BODY_BYTES) {
285	      respond(res, 400, { error: '请求体过大' });
286	      req.destroy();
287	      return;
288	    }
289	    chunks.push(chunk);
290	  }
291	  let payload: unknown;
292	  try {
293	    payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
294	  } catch {
295	    respond(res, 400, { error: '请求体不是有效的 JSON' });
296	    return;
297	  }
298	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
299	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
300	    return;
301	  }
302	  const body = payload as Record<string, unknown>;
303	  for (const field of ['title', 'description'] as const) {
304	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
305	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
306	  }
307	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
308	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
309	    return;
310	  }
311	  const title = (body.title as string).trim();
312	  const description = body.description as string;
313	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
314	  if (!title) { respond(res, 400, { error: '标题去掉首尾空白后不能为空' }); return; }
315	  if (codePoints(title) > MAX_TITLE) { respond(res, 400, { error: `标题最多 ${MAX_TITLE} 个字符` }); return; }
316	  if (!description.trim()) { respond(res, 400, { error: '详细说明必须包含非空白内容' }); return; }
317	  if (codePoints(description) > MAX_DESCRIPTION) { respond(res, 400, { error: `详细说明最多 ${MAX_DESCRIPTION} 个字符` }); return; }
318	  if (codePoints(scenario) > MAX_SCENARIO) { respond(res, 400, { error: `使用场景最多 ${MAX_SCENARIO} 个字符` }); return; }
319	  const idea = {
320	    id: randomUUID(),
321	    title,
322	    description,
323	    scenario,
324	    createdAt: new Date().toISOString(),
325	  };
326	  let records: unknown[];
327	  try {
328	    records = readIdeas();
329	  } catch {
330	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
331	    return;
332	  }
333	  records.unshift(idea);
334	  try {
335	    saveIdeas(records);
336	  } catch {
337	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
338	    return;
339	  }
340	  respond(res, 201, { idea });
341	}
342	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
343	  let route: string;
344	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
345	  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
346	  if (route === '/api/ideas') {
347	    if (req.method === 'POST') {
348	      handleCreateIdea(req, res).catch(() => {
349	        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
350	      });
351	      return;
352	    }
353	    if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }, { allow: 'GET, POST' }); return; }
354	    try {
355	      respond(res, 200, { [RESOURCE]: readIdeas() });
356	    } catch { respond(res, 500, { error: 'unable to read ideas' }); }
357	    return;
358	  }
359	  if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }); return; }
360	  if (route === '/') { respond(res, 200, PAGE, { html: true }); return; }
361	  respond(res, 200, { status: 'ok', product: PRODUCT });
362	});
363	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
364	server.listen(port, host, (): void => {
365	  const address = server.address();
366	  if (address && typeof address !== 'string') {
367	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
368	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
369	  }
370	});
371	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
372	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
373	}
374

