1	import { test, before, after } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { startServer, removeDataDir, type StartedServer } from '../testing/server.ts';
4	
5	// 字段长度上限的接口端到端回归：真实起一份 server.ts，只走公开的
6	// POST/GET /api/ideas。长度规则（与首页表单共用同一套判定）：
7	//   长度按 Unicode 码点累计（Array.from(text).length），标题最多 120、
8	//   详细说明最多 5000、使用场景最多 1000；中文、英文字母、单个 😀 各算一个码点，
9	//   由多个码点组成的文字（旗帜 🇨🇳、ZWJ 表情 😮‍💨、组合字符 é）按各自码点累计。
10	// 标题按去掉首尾空白后的长度判定并保存去空白结果，内部空白仍计入；
11	// 详细说明只要求含非空白内容，长度含原文首尾空白与换行并原样保存；
12	// 使用场景按原文计算与保留，省略或空字符串都可提交。
13	// 本文件要能发现这些回归：把表情算成两个字符（UTF-16 码元）、按传输字节算长度、
14	// 把恰好达到上限的内容错误拒绝、以及把超限内容截断后保存。
15	
16	interface Idea {
17	  id: string;
18	  title: string;
19	  description: string;
20	  scenario: string;
21	  createdAt: string;
22	}
23	
24	let server: StartedServer;
25	
26	before(async () => {
27	  server = await startServer();
28	});
29	
30	after(async () => {
31	  await server.stop();
32	  removeDataDir(server);
33	});
34	
35	async function createIdea(body: unknown): Promise<{ status: number; data: any }> {
36	  const res = await fetch(`${server.origin}/api/ideas`, {
37	    method: 'POST',
38	    headers: { 'content-type': 'application/json' },
39	    body: JSON.stringify(body),
40	  });
41	  return { status: res.status, data: await res.json() };
42	}
43	
44	async function listIdeas(): Promise<Idea[]> {
45	  const res = await fetch(`${server.origin}/api/ideas`);
46	  assert.equal(res.status, 200);
47	  const data = await res.json();
48	  assert.ok(Array.isArray(data.ideas));
49	  return data.ideas as Idea[];
50	}
51	
52	const points = (text: string): number => Array.from(text).length;
53	
