46	function makeElement(tag: string): El {
47	  const node = {
48	    tagName: tag.toUpperCase(),
49	    className: '',
50	    hidden: false,
51	    value: '',
52	    dateTime: '',
53	    children: [],
54	    text: null as string | null,
55	    listeners: {} as Record<string, Array<(event: unknown) => unknown>>,
56	    append(...nodes: El[]): void {
57	      this.children.push(...nodes);
58	    },
59	    replaceChildren(...nodes: El[]): void {
60	      this.children = [...nodes];
61	    },
62	    addEventListener(type: string, fn: (event: unknown) => unknown): void {
63	      (this.listeners[type] ??= []).push(fn);
64	    },
65	    reset(): void {},
66	  };
67	  Object.defineProperty(node, 'textContent', {
68	    get(this: any): string {
69	      return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join('');
70	    },
71	    set(this: any, value: unknown): void {
72	      this.text = String(value);
73	    },
74	  });
75	  return node as El;
76	}
