132	class Harness {
133	  els: Record<string, El> = {};
134	  gets: Gate[] = [];
135	  getsIssued = 0;
136	  posts: Gate[] = [];
137	  postsIssued = 0;
138	  postBodies: unknown[] = [];
139	
140	  constructor(script: string) {
141	    const byId: Map<string, El> = new Map();
142	    const register = (id: string, tag: string, hidden = false): El => {
143	      const node = makeElement(tag);
144	      node.hidden = hidden;
145	      byId.set(id, node);
146	      this.els[id] = node;
147	      return node;
148	    };
149	    const form = register('idea-form', 'form');
150	    const titleInput = register('f-title', 'input');
151	    const descInput = register('f-desc', 'textarea');
152	    const scenarioInput = register('f-scenario', 'textarea');
153	    register('error', 'p', true);
154	    register('success', 'p', true);
155	    register('empty', 'p', true);
156	    register('ideas', 'div');
157	    form.reset = (): void => {
158	      titleInput.value = '';
159	      descInput.value = '';
160	      scenarioInput.value = '';
161	    };
162	    const documentMock = {
163	      getElementById: (id: string): El => byId.get(id)!,
164	      createElement: (tag: string): El => makeElement(tag),
165	    };
166	    const fetchMock = (url: unknown, init?: { method?: string; body?: unknown }): Promise<unknown> => {
167	      const method = init?.method ?? 'GET';
168	      const pending = gate();
169	      if (method === 'POST') {
170	        this.posts.push(pending);
171	        this.postsIssued += 1;
172	        this.postBodies.push(init?.body);
173	      } else {
174	        this.gets.push(pending);
175	        this.getsIssued += 1;
176	      }
177	      return pending.promise;
178	    };
179	    const context = vm.createContext({ console, document: documentMock, fetch: fetchMock });
180	    vm.runInContext(script, context, { filename: 'inline-page-script.js' });
181	  }
