183	  setForm(values: { title?: string; description?: string; scenario?: string }): void {
184	    if (values.title !== undefined) this.els['f-title'].value = values.title;
185	    if (values.description !== undefined) this.els['f-desc'].value = values.description;
186	    if (values.scenario !== undefined) this.els['f-scenario'].value = values.scenario;
187	  }
