847	// 提交提示归属：成功或失败提示只属于最近一次点击提交。用户可以在上一条请求还没返回时
848	// 再次点击提交，更早请求迟到的任何结果都不能改动当前提示；但旧请求被服务确认保存的意见
849	// 仍必须进入列表。下列用例精确控制两个 POST 的返回先后与结果类型。
850	
851	function settleGate(g: Gate, outcome: 'network-error' | 'server-reject' | 'broken-json' | 'missing-idea'): void {
852	  if (outcome === 'network-error') {
853	    g.reject(new TypeError('Failed to fetch'));
854	  } else if (outcome === 'server-reject') {
855	    g.resolve(jsonResponse(400, { error: '较早一次提交被拒绝' }));
856	  } else if (outcome === 'broken-json') {
857	    g.resolve(brokenJsonResponse(201));
858	  } else {
859	    g.resolve(jsonResponse(201, { saved: true }));
860	  }
861	}
862	
863	const STALE_FAILURE_KINDS = [
864	  { name: '网络错误', outcome: 'network-error' as const },
865	  { name: '服务拒绝（400）', outcome: 'server-reject' as const },
866	  { name: '201 但响应无法解析', outcome: 'broken-json' as const },
867	  { name: '201 但内容不完整（缺 idea）', outcome: 'missing-idea' as const },
868	];
