1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { mkdtempSync, rmSync } from 'node:fs';
4	import { tmpdir } from 'node:os';
5	import { join } from 'node:path';
6	import { startServer, type StartedServer } from '../testing/server.ts';
7	
8	// 意见保存功能的持久化回归：只走公开入口（POST/GET /api/ideas），在真实进程上
9	// 验证「提交成功 → 正常停止（SIGTERM）→ 用同一 --data-dir 再次启动」这一已有行为。
10	// 基线一律以 POST 201 返回的记录为准（即标题已 trim、正文与场景保留原空白的处理结果），
11	// 回归需要能发现：保存内容丢失、记录被合并/替换、id 或 createdAt 被重新生成、次序变化、
12	// 以及一条意见的文字被归到另一条意见名下。
13	
14	interface Idea {
15	  id: string;
16	  title: string;
17	  description: string;
18	  scenario: string;
19	  createdAt: string;
20	}
21	
22	function freshDir(): string {
23	  return mkdtempSync(join(tmpdir(), 'featureharbor-persist-'));
24	}
25	
26	async function listIdeas(server: StartedServer): Promise<Idea[]> {
27	  const res = await fetch(`${server.origin}/api/ideas`);
28	  assert.equal(res.status, 200);
29	  const data = await res.json();
30	  assert.ok(Array.isArray(data.ideas));
31	  return data.ideas as Idea[];
32	}
33	
34	async function createIdea(
35	  server: StartedServer,
36	  body: unknown,
37	): Promise<{ status: number; data: any }> {
38	  const res = await fetch(`${server.origin}/api/ideas`, {
39	    method: 'POST',
40	    headers: { 'content-type': 'application/json' },
41	    body: JSON.stringify(body),
42	  });
43	  return { status: res.status, data: await res.json() };
44	}
45	
46	// 正常停止当前进程，再用同一数据目录启动一份新服务（新进程、新端口）。
47	async function restart(server: StartedServer): Promise<StartedServer> {
48	  const dir = server.dataDir;
49	  await server.stop();
50	  return startServer(dir);
51	}
52	
53	// 兜底停止：即使重复调用也不挂住测试（stop 内部另有 SIGKILL 兜底）。
54	async function safeStop(server: StartedServer): Promise<void> {
55	  await Promise.race([
56	    server.stop(),
57	    new Promise<void>((resolve) => setTimeout(resolve, 2000)),
58	  ]);
59	}
60	
61	test('停止后用同一数据目录重启：原有意见数量、标识、提交时间、逐条文字与次序完整保留', async () => {
62	  const dir = freshDir();
63	  let server = await startServer(dir);
64	  try {
65	    // 故意覆盖易错内容：首尾空白标题（应被 trim）、保留空白/换行/制表符的正文、
66	    // 省略场景与显式空场景、中文、emoji、看起来像网页标记的文本；
67	    // 其中第 2、3 条标题与正文完全相同，只能靠 id 区分，重新读取时不得合成一条。
68	    const payloads: unknown[] = [
69	      {
70	        title: '  深色模式  ',
71	        description: '  希望界面\n支持深色模式\t与强调色。 ',
72	        // scenario 省略，按现有规则保存为空字符串
73	      },
74	      {
75	        title: '重复标题',
76	        description: '重复说明\n第二行 <b>加粗</b> 😀',
77	        scenario: '夜间 🌙 使用\n场景第二行',
78	      },
79	      {
80	        title: '重复标题',
81	        description: '重复说明\n第二行 <b>加粗</b> 😀',
82	        scenario: '',
83	      },
84	      {
85	        title: ' 网页标记与表情 ',
86	        description: '多行\n\n保留空行：<p>段落</p><script>alert("x")</script> 🎉中文',
87	        scenario: '  场景首尾空白保留  ',
88	      },
89	    ];
90	
91	    const saved: Idea[] = [];
92	    for (const payload of payloads) {
93	      const { status, data } = await createIdea(server, payload);
94	      assert.equal(status, 201);
95	      saved.push(data.idea as Idea);
96	    }
97	
98	    // 先确认 POST 返回的就是现有提交规则处理后的结果
99	    assert.equal(saved[0].title, '深色模式');
